class PayrollAccount { private double basicSalary, bonus; PayrollAccount(double salary) { if (salary < 0) { basicSalary=0; System.out.println("Negative salary changed to 0"); } else basicSalary=salary; } void creditBonus(double amount) { if (amount <= 0) System.out.println("Bonus rejected"); else { bonus += amount; System.out.println("Bonus credited: Rs " + amount); } } void deductTax(double percent) { if (percent < 0 || percent > 100) System.out.println("Invalid tax percentage"); else { basicSalary -= basicSalary * percent / 100; System.out.println("Tax deducted: " + percent + "%"); } } double getNetSalary() { return basicSalary + bonus; } }
public class PayrollAccountDemo { public static void main(String[] args) { PayrollAccount account = new PayrollAccount(50000); account.creditBonus(5000); account.deductTax(10); System.out.println("Net salary: Rs " + account.getNetSalary()); } }
